  function makeRoot(){if(root)return;injectStyle();root=document.createElement('main');root.id='colorTrainer';root.className='section hidden';var app=q('.app'),footer=app&&q('footer.copyright',app);if(app){if(footer)app.insertBefore(root,footer);else app.appendChild(root);}}
  function hideOther(){['home','library','quiz','review','stats','examV13','binderTrainer','substrateTrainer'].forEach(function(id){var e=byId(id);if(e)e.classList.add('hidden');});if(root)root.classList.remove('hidden');var hb=byId('homeBtn');if(hb)hb.classList.remove('hidden');try{window.scrollTo({top:0,behavior:'smooth'});}catch(e){}}
  function close(){if(root)root.classList.add('hidden');current=null;}
  function open(){makeRoot();hideOther();renderHome();}

  function findDepthGroup(){var dash=byId('v17Dashboard');if(!dash)return null;var groups=qa('.v17Group',dash);for(var i=0;i<groups.length;i++){var t=q('.v17GroupTitle',groups[i]);if(t&&t.textContent.trim()==='Vertiefen')return groups[i];}return null;}
  function injectLauncher(){if(byId('ctLauncher'))return;var dash=byId('v17Dashboard');if(!dash)return;var section=findDepthGroup();if(!section){section=document.createElement('section');section.className='v17Group';section.innerHTML='<div class="v17GroupHead"><div class="v17GroupTitle">Vertiefen</div><div class="v17GroupHint">Thema wirklich verstehen</div></div><div class="v17ActionGrid"></div>';var utility=q('.v17Utility',dash);if(utility)dash.insertBefore(section,utility);else dash.appendChild(section);}var grid=q('.v17ActionGrid',section);if(!grid)return;var b=document.createElement('button');b.type='button';b.id='ctLauncher';b.className='v17Action ctLaunch';b.innerHTML='<span class="v17ActionIcon" aria-hidden="true">🎨</span><span><span class="v17ActionTitle">Farbenlehre-Trainer</span><span class="v17ActionText">Verstehen · mischen · anwenden.</span></span><span class="v17ActionArrow">›</span>';b.onclick=open;grid.appendChild(b);updateLauncher();}
  function updateLauncher(){var b=byId('ctLauncher');if(!b)return;var t=q('.v17ActionText',b);if(t)t.innerHTML='Verstehen · mischen · anwenden.<span class="ctLaunchProgress">'+completedLessons()+'/'+activeLessonCount()+' aktive Lektionen bestanden</span>';}

  function blockStatus(b){if(!b.ready)return 'KOMMT SPÄTER';if(blockPassed(b.id))return 'BESTANDEN';if(b.id>state.unlockedBlock)return 'GESPERRT';return 'STARTEN';}
  function renderHome(){makeRoot();current=null;var activeDone=LESSONS.filter(function(l){return l.block<=ACTIVE_BLOCKS&&lessonPassed(l.id);}).length;var pct=Math.round(100*activeDone/activeLessonCount());var blocksDone=0;for(var bdi=1;bdi<=ACTIVE_BLOCKS;bdi++)if(blockPassed(bdi))blocksDone++;root.innerHTML='<div class="card ctHead"><div class="ctTop"><div><div class="ctEye">HF 1 · Technik & Gestaltung</div><div class="ctTitle">Farbenlehre-Trainer 🎨</div><div class="ctLead">Dinogebiss komplett: 8 Lernblöcke von Grundlagen bis BFS 25/26. Lernen, anwenden, Block-Checks bestehen und anschließend den Farbenlehre-Gesamttest meistern.</div></div><div class="ctMeta"><span class="badge">'+EXERCISES.length+' Aufgaben</span><span class="badge">'+activeLessonCount()+' aktive Lektionen</span><span class="badge">'+ACTIVE_BLOCKS+'/8 Blöcke aktiv</span></div></div><div class="ctProgress"><span style="width:'+pct+'%"></span></div></div><div class="ctStats"><div class="ctStat"><span>AKTIVE LEKTIONEN</span><strong>'+activeDone+'/'+activeLessonCount()+'</strong></div><div class="ctStat"><span>BLOCKS</span><strong>'+blocksDone+'/'+ACTIVE_BLOCKS+'</strong></div><div class="ctStat"><span>FEHLERPOOL</span><strong>'+totalMistakes()+'</strong></div><div class="ctStat"><span>BESTEHEN</span><strong>'+PASS_PCT+' %</strong></div></div><div class="ctBlocks" id="ctBlocks"></div><div class="ctBlockTest"><span><strong>Farbenlehre-Gesamttest</strong><div>'+FINAL_TEST_SIZE+' Aufgaben · alle 8 Blöcke · Bestehen ab '+PASS_PCT+' %</div></span><button class="btn primary" id="ctFinalTest">Gesamttest starten</button></div><div class="ctActions"><button class="btn" id="ctErrors">↺ Fehler wiederholen</button><button class="btn" id="ctReset">Trainer zurücksetzen</button></div>';
    var grid=byId('ctBlocks');BLOCKS.forEach(function(b){var locked=!b.ready||b.id>state.unlockedBlock;var el=document.createElement('button');el.type='button';el.className='ctBlock'+(blockPassed(b.id)?' done':'');el.disabled=locked;el.innerHTML='<span class="ctIcon">'+esc(b.icon)+'</span><span><span class="ctBlockTitle">'+b.id+'. '+esc(b.title)+'</span><span class="ctBlockSub">'+esc(b.sub)+'</span></span><span class="ctState">'+blockStatus(b)+'</span>';if(b.ready)el.onclick=function(){openBlock(b.id);};grid.appendChild(el);});
    var ft=byId('ctFinalTest');if(ft){ft.disabled=!allBlocksPassed();var fs=fState();ft.textContent=fs.runs?'Gesamttest · BEST '+fs.best+' %':'Gesamttest starten';ft.onclick=startFinalTest;}byId('ctErrors').disabled=totalMistakes()===0;byId('ctErrors').onclick=startMistakeRound;byId('ctReset').onclick=resetState;updateLauncher();
  }

  function header(eye,title,sub,backFn){return '<div class="card ctHeader"><div class="ctHeaderTop"><div><div class="ctEye">'+esc(eye)+'</div><div class="ctHeaderTitle">'+esc(title)+'</div><div class="ctHeaderSub">'+esc(sub)+'</div></div><button class="btn" id="ctBack">← Zurück</button></div></div>';}
  function openBlock(id){var b=blockById(id);if(!b||!b.ready||id>state.unlockedBlock)return;state.lastBlock=id;saveState();current={kind:'block',block:id};root.innerHTML=header('Lernblock '+id+' von 8',b.title,b.sub)+'<div class="ctLessonGrid" id="ctLessons"></div><div class="ctBlockTest"><span><strong>Block-Check</strong><div>'+BLOCK_TEST_SIZE+' gemischte Aufgaben · Freischaltung ab '+PASS_PCT+' % · erst nach allen Lektionen</div></span><button class="btn primary" id="ctBlockTestBtn">Block prüfen</button></div>';byId('ctBack').onclick=renderHome;var grid=byId('ctLessons');blockLessons(id).forEach(function(l,idx){var prevOk=idx===0||lessonPassed(blockLessons(id)[idx-1].id),st=lState(l.id),el=document.createElement('button');el.type='button';el.className='ctLesson'+(st.passed?' passed':'');el.disabled=!prevOk;el.innerHTML='<span class="ctLessonNum">'+(st.passed?'✓':(idx+1))+'</span><span><span class="ctLessonTitle">'+esc(l.title)+'</span><span class="ctLessonSub">'+esc(l.sub)+'</span></span><span class="ctLessonScore">'+(st.runs?'BEST '+st.best+' %':(prevOk?'START':'GESPERRT'))+'</span>';el.onclick=function(){openLesson(l.id);};grid.appendChild(el);});var bt=byId('ctBlockTestBtn');bt.disabled=!blockLessonsPassed(id);bt.onclick=function(){startBlockTest(id);};}

  function openLesson(id){var l=lessonById(id);if(!l)return;state.lastLesson=id;saveState();current={kind:'learn',lesson:id,slide:0};renderLearning();}
  function renderLearning(){var l=lessonById(current.lesson),cards=LEARNING[l.id],i=current.slide||0,card=cards[i];root.innerHTML=header('Block '+l.block+' · Lernen',l.title,l.sub)+'<div class="card ctLearn"><div class="ctLearnCard"><h3>'+esc(card.title)+'</h3><p>'+esc(card.text)+'</p><div class="ctMemo">'+esc(card.memo)+'</div></div><div class="ctLearnNav"><button class="btn" id="ctPrev" '+(i===0?'disabled':'')+'>← Vorheriges</button><button class="btn primary" id="ctLearnNext">'+(i===cards.length-1?'Zur Übung':'Weiter →')+'</button></div></div>';byId('ctBack').onclick=function(){openBlock(l.block);};byId('ctPrev').onclick=function(){if(current.slide>0){current.slide--;renderLearning();}};byId('ctLearnNext').onclick=function(){if(current.slide<cards.length-1){current.slide++;renderLearning();return;}lState(l.id).read=true;saveState();startLessonQuiz(l.id);};}

  function chooseQuestions(pool,count){var a=pool.map(function(item){return {item:item,seen:Number(state.seen[item.id])||0,r:Math.random()};});a.sort(function(x,y){return x.seen-y.seen||x.r-y.r;});return a.slice(0,Math.min(count,a.length)).map(function(x){return x.item;});}
  function prepared(item){var opts=item.options.map(function(t,i){return {text:t,orig:i};});opts=shuffle(opts);return {source:item,display:opts,correctPos:opts.findIndex(function(x){return x.orig===item.correct;})};}
  function startLessonQuiz(id){var l=lessonById(id),items=chooseQuestions(lessonQuestions(id),LESSON_ROUND).map(prepared);items.forEach(function(x){state.seen[x.source.id]=(Number(state.seen[x.source.id])||0)+1;});saveState();current={kind:'quiz',mode:'lesson',lesson:id,block:l.block,items:items,index:0,score:0,answered:false};renderQuestion();}
  function startBlockTest(id){var pool=blockQuestions(id),byLevel={basis:[],verstehen:[],anwenden:[]};pool.forEach(function(x){(byLevel[x.level]||byLevel.verstehen).push(x);});var pick=[];[['basis',4],['verstehen',4],['anwenden',4]].forEach(function(spec){pick=pick.concat(chooseQuestions(byLevel[spec[0]],spec[1]));});pick=shuffle(pick).slice(0,BLOCK_TEST_SIZE);pick.forEach(function(x){state.seen[x.id]=(Number(state.seen[x.id])||0)+1;});saveState();current={kind:'quiz',mode:'block',block:id,items:pick.map(prepared),index:0,score:0,answered:false};renderQuestion();}
  function startFinalTest(){if(!allBlocksPassed())return renderHome();var pick=[];for(var b=1;b<=ACTIVE_BLOCKS;b++){var pool=blockQuestions(b),byLevel={basis:[],verstehen:[],anwenden:[]};pool.forEach(function(x){(byLevel[x.level]||byLevel.verstehen).push(x);});pick=pick.concat(chooseQuestions(byLevel.basis,1),chooseQuestions(byLevel.verstehen,1),chooseQuestions(byLevel.anwenden,2));}pick=shuffle(pick).slice(0,FINAL_TEST_SIZE);pick.forEach(function(x){state.seen[x.id]=(Number(state.seen[x.id])||0)+1;});saveState();current={kind:'quiz',mode:'final',block:null,items:pick.map(prepared),index:0,score:0,answered:false};renderQuestion();}
  function startMistakeRound(){var ids=Object.keys(state.mistakes).filter(function(id){return state.mistakes[id]&&state.mistakes[id].wrong>0&&exerciseById(id);});if(!ids.length)return renderHome();ids.sort(function(a,b){return (state.mistakes[b].wrong||0)-(state.mistakes[a].wrong||0);});var items=shuffle(ids.slice(0,10).map(exerciseById)).map(prepared);current={kind:'quiz',mode:'mistakes',block:null,items:items,index:0,score:0,answered:false};renderQuestion();}
  function renderQuestion(){var c=current,item=c.items[c.index],src=item.source,eye=c.mode==='lesson'?'Lektionsübung':c.mode==='block'?'Block-Check':c.mode==='final'?'Gesamttest':'Fehlerwiederholung',sub=c.mode==='lesson'?lessonById(c.lesson).title:c.mode==='block'?blockById(c.block).title:c.mode==='final'?'Farbenlehre · alle 8 Blöcke':'Unsichere Aufgaben erneut festigen';root.innerHTML=header(eye,sub,'Aufgabe '+(c.index+1)+' von '+c.items.length)+'<div class="card ctQuiz"><div class="ctQMeta"><span class="badge">'+(c.index+1)+' / '+c.items.length+'</span><span class="badge">'+esc(src.level.toUpperCase())+'</span></div><div class="ctQuestion">'+esc(src.prompt)+'</div><div class="ctAnswers" id="ctAnswers"></div><div id="ctFeedback"></div></div>';byId('ctBack').onclick=function(){if(c.mode==='lesson')openBlock(c.block);else renderHome();};var box=byId('ctAnswers');item.display.forEach(function(o,pos){var b=document.createElement('button');b.type='button';b.className='ctAnswer';b.dataset.orig=o.orig;b.innerHTML='<span class="ctLetter">'+String.fromCharCode(65+pos)+'</span><span>'+esc(o.text)+'</span>';b.onclick=function(){answer(pos,b);};box.appendChild(b);});}
  function answer(pos,btn){if(!current||current.answered)return;current.answered=true;var item=current.items[current.index],src=item.source,ok=pos===item.correctPos;if(ok)current.score++;var m=state.mistakes[src.id]||(state.mistakes[src.id]={wrong:0,right:0});if(ok){m.right++;if(m.wrong>0)m.wrong=Math.max(0,m.wrong-1);}else m.wrong++;saveState();qa('.ctAnswer',byId('ctAnswers')).forEach(function(b,i){b.disabled=true;if(i===item.correctPos)b.classList.add('correct');else if(b===btn)b.classList.add('wrong');});byId('ctFeedback').innerHTML='<div class="ctFeedback '+(ok?'good':'bad')+'"><strong>'+(ok?'Richtig.':'Noch nicht.')+'</strong> '+(ok?'Die Zuordnung sitzt.':'Die richtige Antwort ist markiert.')+'<div class="ctQuizActions"><button class="btn" id="ctWhy">Warum?</button><button class="btn primary" id="ctNext">'+(current.index+1<current.items.length?'Weiter':'Auswerten')+'</button></div><div class="ctWhy hidden" id="ctWhyBox">'+esc(src.why)+'</div></div>';byId('ctWhy').onclick=function(){byId('ctWhyBox').classList.toggle('hidden');};byId('ctNext').onclick=nextQuestion;}
  function nextQuestion(){if(!current||!current.answered)return;if(current.index+1<current.items.length){current.index++;current.answered=false;renderQuestion();}else finishQuiz();}
  function finishQuiz(){var c=current,total=c.items.length,score=c.score,pct=Math.round(100*score/total),passed=pct>=PASS_PCT,title='',text='',again=function(){},overview=renderHome;if(c.mode==='lesson'){var st=lState(c.lesson);st.runs++;st.best=Math.max(st.best,pct);if(passed)st.passed=true;saveState();var l=lessonById(c.lesson);title=passed?'Lektion bestanden':'Lektion noch nicht bestanden';text='Bestwert: '+st.best+' %. '+(passed?'Die nächste Lektion ist freigeschaltet.':'Für das Bestehen brauchst du mindestens '+PASS_PCT+' %.');again=function(){startLessonQuiz(c.lesson);};overview=function(){openBlock(l.block);};}else if(c.mode==='block'){var bs=bState(c.block);bs.runs++;bs.best=Math.max(bs.best,pct);if(passed){bs.passed=true;if(c.block<ACTIVE_BLOCKS)state.unlockedBlock=Math.max(state.unlockedBlock,c.block+1);}saveState();title=passed?'Block bestanden':'Block noch nicht bestanden';text='Bestwert: '+bs.best+' %. '+(passed?(c.block<ACTIVE_BLOCKS?'Der nächste Lernblock ist freigeschaltet.':'Alle 8 Lernblöcke sind abgeschlossen. Jetzt ist der Farbenlehre-Gesamttest freigeschaltet.'):'Für die Freischaltung brauchst du mindestens '+PASS_PCT+' %.');again=function(){startBlockTest(c.block);};overview=renderHome;}else if(c.mode==='final'){var fs=fState();fs.runs++;fs.best=Math.max(fs.best,pct);if(passed)fs.passed=true;saveState();title=passed?'Gesamttest bestanden':'Gesamttest noch nicht bestanden';text='Bestwert: '+fs.best+' %. '+(passed?'Dinogebiss komplett: Farbenlehre-Lernpfad und Gesamttest sind bestanden.':'Für den Gesamttest brauchst du mindestens '+PASS_PCT+' %.');again=startFinalTest;overview=renderHome;}else{title='Fehlerrunde abgeschlossen';text='Richtig gelöste Fehler werden schrittweise aus dem Wiederholungspool abgebaut.';again=startMistakeRound;overview=renderHome;}root.innerHTML=header('Auswertung',title,pct+' % erreicht')+'<div class="card ctResult"><div class="ctScore">'+score+'/'+total+'</div><div class="ctResultTitle">'+esc(title)+'</div><div class="ctResultText">'+esc(text)+'</div><div class="ctQuizActions" style="margin-top:16px"><button class="btn" id="ctAgain">Wiederholen</button><button class="btn primary" id="ctOverview">Weiter</button></div></div>';byId('ctBack').onclick=overview;byId('ctAgain').onclick=again;byId('ctOverview').onclick=overview;current=null;updateLauncher();}

  function resetState(){if(!window.confirm('Farbenlehre-Trainer wirklich zurücksetzen?\n\nNur der Fortschritt dieses Trainers wird gelöscht. Die 899 normalen Lernkarten, Quizdaten, Prüfungen und die anderen Spezialtrainer bleiben erhalten.'))return;state=defaultState();saveState();renderHome();}
  function hookHomeButton(){var b=byId('homeBtn');if(!b||b.dataset.ctHooked==='1')return;b.addEventListener('click',function(){if(root&&!root.classList.contains('hidden'))close();});b.dataset.ctHooked='1';}
  function exportState(){return JSON.parse(JSON.stringify(state));}
  function importState(s){if(!s||typeof s!=='object')return false;try{state=sanitizeState(JSON.parse(JSON.stringify(s)));saveState();return true;}catch(e){return false;}}
  function clearState(){try{localStorage.removeItem(STORAGE_KEY);}catch(e){}state=defaultState();updateLauncher();}
  function getState(){return exportState();}

  function boot(){makeRoot();injectLauncher();hookHomeButton();var tries=0,t=setInterval(function(){tries++;injectLauncher();hookHomeButton();if(byId('ctLauncher')||tries>40)clearInterval(t);},120);}
  window.FachteilColorTrainerV24={open:open,close:close,exportState:exportState,importState:importState,clearState:clearState,getState:getState,blocks:BLOCKS,lessons:LESSONS,exercises:EXERCISES,validation:VALIDATION,finalTestSize:FINAL_TEST_SIZE};
  if(typeof document!=='undefined'){if(document.readyState==='loading')document.addEventListener('DOMContentLoaded',boot);else setTimeout(boot,0);}
